model:
rachana: 1
sutra: dms-score
version: 1
description: 
match: { kind: dms-score, priority: 10 }
title: { pill: "Protein engineering · Deep mutational scan score", id: "$.SCORE_ID" }
strip:
  - { label: "Score id", bind: "$.SCORE_ID" }
  - { label: "Mutation", bind: "$.MUTATION" }
  - { label: "Assay", bind: "$.ASSAY" }
  - { label: "Score", bind: "$.SCORE" }
  - { label: "Se", bind: "$.SE", emphasis: true }
panels:
  - id: record
    kind: kv
    title: "Deep mutational scan score"
    columns:
      - { label: "Score id", bind: "$.SCORE_ID" }
      - { label: "Protein", bind: "link($.PROTEIN, 'protein')" }
      - { label: "Pos", bind: "$.POS", fmt: "amount0" }
      - { label: "Aa ref", bind: "$.AA_REF" }
      - { label: "Aa", bind: "$.AA" }
      - { label: "Mutation", bind: "$.MUTATION" }
      - { label: "Assay", bind: "$.ASSAY" }
      - { label: "Score", bind: "$.SCORE" }
      - { label: "Se", bind: "$.SE" }
      - { label: "Replicates", bind: "$.REPLICATES", fmt: "amount0" }
keys: { F9: "raw" }
